\label{lem:graph}
For every proper ideal \(Q\subset A\),
\begin{equation}\label{eq:graph-bound}
e_{\mathrm{HS}}(A/Q)\leqe_{\mathrm{HS}}(B/QB)\leq d\,e_{\mathrm{HS}}(A/Q).
\end{equation}

\label{thm:flat-segre}
Let \(0\ne J\subsetneq A\), let \(I=JB\), and let \(d=\deg F\).
Then
\begin{equation}\label{eq:flat-segre-bounds}
e_j(J;A)\leq e_j(I;B)\leq d\,e_j(J;A),
\qquad 1\leq j\leq n,
\end{equation}
and the last Segre number satisfies
\begin{equation}\label{eq:j-degree}
e_n(I;B)=d\,e_n(J;A).
\end{equation}
Equivalently,
\(c_i(J;A)\leq c_i(I;B)\leq d\,c_i(J;A)\), with
equality on the right for \(i=0\).

\label{lem:first-coefficient}
Let \(R\) be regular local analytic of dimension \(n\), and
let \(K\subseteq L\) be proper nonzero ideals with
\(\dim R/K=\dim R/L=s\). Then
\begin{equation}\label{eq:first-coefficient}
c_s(K;R)\geq c_s(L;R).
\end{equation}
If \(L\) is equimultiple, then
\(c_i(K;R)\geq c_i(L;R)\) for every \(i\).

\label{cor:isolated-degree}
Under the hypotheses of Theorem~\ref{thm:isolated}, if
\(g\circ F=uh\), then
\begin{equation}\label{eq:isolated-degree-bound}
\mu(h)\geq d\,\mu(g).
\end{equation}

\label{thm:reduced-lex}
Under \eqref{eq:reduced-hypothesis},
\begin{equation}\label{eq:reduced-lex}
\mathbf e(J(h);B)\geq_{\mathrm{lex}}\mathbf e(J(g);A).
\end{equation}
No equality of the dimensions of \(\Sigma(g)\) and
\(\Sigma(h)\) is required. Equivalently,
\[
\bigl(\lambda^{n-1}_{\mathrm{gen}}(h),\ldots,\lambda^{0}_{\mathrm{gen}}(h)\bigr)
\geq_{\mathrm{lex}}
\bigl(\lambda^{n-1}_{\mathrm{gen}}(g),\ldots,\lambda^{0}_{\mathrm{gen}}(g)\bigr).
\]

\label{thm:curve-equality}
Under \eqref{eq:curve-hypothesis},
\begin{align}
c_1(K)&\geq c_1(I)\geq c_1(J),\label{eq:curve-sandwich}\\
(c_1(K),c_0(K))&\geq_{\mathrm{lex}}(c_1(J),c_0(J)).
\label{eq:curve-lex}
\end{align}
If \(c_1(K)=c_1(I)\), then
\begin{equation}\label{eq:curve-strong-top}
c_0(K)\geq d\,c_0(J).
\end{equation}
In that case all Segre numbers and generic L\^e numbers are
componentwise nondecreasing.

\label{cor:curve-cases}
Under \eqref{eq:curve-hypothesis}, assume at least one of:
\begin{enumerate}
\item \(c_1(J(h))=c_1(J(g))\);
\item \(J(g)\) is equimultiple;
\item no irreducible component of \(\Sigma(h)\) is contained
in \(R_F=V(\det DF)\).
\end{enumerate}
Then all Segre numbers and generic L\^e numbers are
componentwise nondecreasing. Moreover,
\[
\lambda^{0}_{\mathrm{gen}}(h)=e_n(J(h))\geq d\,e_n(J(g))=d\,\lambda^{0}_{\mathrm{gen}}(g).
\]
In condition (3), the assumption that the pullback divisor is
reduced may be replaced by the weaker assumption that its
reduced support is irreducible.

\label{prop:transversal}
Assume the following conditions.
\begin{enumerate}
\item Every \(C_\alpha\) is the image of at least one
\(D_\beta\).
\item Whenever \(F(D_\beta)=C_\alpha\), at general points
\(p\in D_\beta\), \(q=F(p)\in C_\alpha\), there exist
smooth transverse slices \(S_p,T_q\), of dimension \(n-1\),
such that \(F(S_p)\subseteq T_q\) and
\(F|_{S_p}:(S_p,p)\to(T_q,q)\) is finite. The restricted
functions \(h|_{S_p}\), \(g|_{T_q}\) are reduced with
isolated critical points and compute their respective generic
transversal Milnor numbers.
\end{enumerate}
Then
\begin{equation}\label{eq:transverse-mu}
\mu_{D_\beta}^\perp(h)\geq\mu_{C_\alpha}^\perp(g)
\quad\text{whenever }F(D_\beta)=C_\alpha,
\end{equation}
and there is an inequality of effective cycles
\begin{equation}\label{eq:cycle-pushforward}
F_*\Lambda_h^1\geq\Lambda_g^1.
\end{equation}
For a general target linear form \(L\),
\begin{equation}\label{eq:pullback-cut}
\bigl(\Lambda_h^1\cdot V(L\circ F)\bigr)_0
\geq\bigl(\Lambda_g^1\cdot V(L)\bigr)_0
=\lambda^{1}_{\mathrm{gen}}(g).
\end{equation}

\label{cor:transversal-origin}
Under the hypotheses of Proposition~\ref{prop:transversal},
suppose that one can choose \(L\) as there with
\begin{equation}\label{eq:cut-realizes-multiplicity}
\bigl(\Lambda_h^1\cdot V(L\circ F)\bigr)_0
=\operatorname{mult}_0\Lambda_h^1.
\end{equation}
Then \(\lambda^{1}_{\mathrm{gen}}(h)\geq\lambda^{1}_{\mathrm{gen}}(g)\). If in addition
\(J(g)\) is equimultiple, all Segre numbers and generic
L\^e numbers are componentwise nondecreasing, for any \(r\).
